{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Publicly accessible database instance",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The database instance allows access from 0.0.0.0/0, which exposes it to the entire internet. This increases the risk of unauthorized access."
    },
    {
      "check_id": "CKV_GCP_16",
      "title": "SSL not enforced for database connections",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The `require_ssl` setting is disabled, which means database connections are not required to use SSL. This can lead to unencrypted data transmission."
    },
    {
      "check_id": "CKV_GCP_18",
      "title": "Deletion protection disabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The `deletion_protection` setting is disabled, which increases the risk of accidental or malicious deletion of the database instance."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n  }\n  deletion_protection = true\n}",
  "fix_summary": "Removed the public IP access (0.0.0.0/0) from the authorized networks, enforced SSL for database connections, and enabled deletion protection to prevent accidental or malicious deletion of the database instance."
}
